-- Columns dropped from brz_customer:
--   c_comment                    free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)

with source as (
    {{ deduplicate(ref('brz_customer'), partition_by=['c_custkey']) }}
)

select
    -- keys
    c_custkey::varchar                                  as customer_id,
    c_nationkey::varchar                                as nation_id,

    -- attributes
    trim(c_name)::varchar                               as customer_name,
    trim(c_address)::varchar                            as customer_address,
    trim(c_phone)::varchar                              as phone,
    -- TPC-H phones are "CC-XXX-XXX-XXXX": the prefix is the country code
    split_part(trim(c_phone), '-', 1)::number(38, 0)    as phone_country_code,
    {{ clean_label('c_mktsegment') }}::varchar          as market_segment,

    -- measures
    c_acctbal::number(12, 2)                            as account_balance,
    c_acctbal < 0                                       as has_negative_balance,

    _loaded_at
from source
